/// `DTB_DEFAULT_ENTRIES`; null where `getarch.c` has no entry for the core.
pub fn arm_dtb(core: coretypes.ArmCoreType) ?i32 {
    return switch (core) {
        .armv5 => 64,
        .armv6 => 64,
        .armv7 => 64,
        .neon => 64,
        .vfpv4 => 128,
        .cortexa9 => 128,
        .cortexa15 => 128,
    };
}

