/// `DTB_DEFAULT_ENTRIES`; null where `getarch.c` has no entry for the core.
pub fn power32_dtb(core: coretypes.PowerCoreType) ?i32 {
    return switch (core) {
        .unknown => null,
        .power6 => 128,
        .power8 => 128,
        .power9 => 128,
        .power10 => 128,
        .power3 => 256,
        .power4 => 128,
        .power5 => 128,
        .ppc970 => 128,
        .cell => 128,
        .ppc440 => 64,
        .ppc440fp2 => 64,
        .ppcg4 => 128,
    };
}

