/// `DTB_DEFAULT_ENTRIES`; null where `getarch.c` has no entry for the core.
pub fn riscv64_dtb(core: coretypes.RiscvCoreType) ?i32 {
    return switch (core) {
        .riscv64_generic => 128,
        .riscv64_zvl128b => 128,
