/// `DTB_DEFAULT_ENTRIES`; null where `getarch.c` has no entry for the core.
pub fn mips64_dtb(core: coretypes.MipsCoreType) ?i32 {
    return switch (core) {
        .mips64_generic => 64,
        .loongson3r3 => 64,
        .loongson3r4 => 64,
        .unknown => null,
        .mips24k => 64,
        .mips1004k => 64,
        .p5600 => 64,
        .i6400 => 64,
        .i6500 => 64,
        .p6600 => 64,
    };
}

